'use strict';
/* Materiais de Apoio — parte D: Pontuação (norma do português europeu, com o Acordo Ortográfico de 1990).
   Mesmo formato das partes A a C. Os exemplos sem autor são frases criadas para ilustrar a regra.
   Base: Cunha e Cintra, «Nova Gramática do Português Contemporâneo»; Prontuário e FLiP; respostas do Ciberdúvidas da Língua Portuguesa. */
SUPPORT.push({ key:'pontuacao', name:'Pontuação', kicker:'Pontuação',
  intro:'Os sinais de pontuação dizem ao leitor como ler: onde respirar, o que pertence ao quê, quem está a falar, o que é pergunta, citação ou aparte. Há regras firmes (não se separa o sujeito do verbo com vírgula) e zonas de escolha (uma vírgula de ritmo, um ponto e vírgula no lugar de um ponto). As fichas seguem a norma do português europeu e o Acordo Ortográfico de 1990 — segundo o qual se escreve «ponto e vírgula» e «dois pontos» sem hífen — e assinalam onde os autores, as editoras e o Brasil fazem diferente.',
  groups:[

  { name:'Sinais que fecham a frase', items:[
    { n:'Ponto final', a:'Ponto · ponto parágrafo · ponto final de texto',
      d:'Marca o fim de uma frase declarativa e a pausa mais longa dentro de um parágrafo. Chama-se «ponto parágrafo» quando a frase seguinte começa noutra linha, e «ponto final» em sentido estrito no fim do texto.',
      u:'Use-o sempre que uma ideia está completa. A seguir vem maiúscula. Duas orações independentes podem ligar-se por vírgula («Chegou, sentou-se.»), mas quando têm uma relação forte (causa, contraste) a vírgula sozinha pode ficar fraca — um ponto, um ponto e vírgula ou uma conjunção tornam a relação clara. Na narrativa, o ponto é o principal instrumento de ritmo: frases curtas aceleram, cortam, dão peso à última palavra.',
      c:'Nunca se repete o ponto: se a frase acaba numa abreviatura («etc.», «Sr.»), o ponto da abreviatura serve de ponto final. Não se põe ponto final em títulos, legendas curtas, nem depois de ponto de interrogação, exclamação ou reticências. Um ponto entre o sujeito e o verbo é erro, não estilo.',
      x:['«Fechou a porta. Lá fora, a chuva continuava.»', 'Abreviatura no fim: «Trouxe pão, queijo, fruta, etc.» (e não «etc..»).', 'Ritmo: «Esperou. Ninguém veio. Esperou mais.»'],
      s:['Frase curta', 'Ritmo da frase', 'Maiúsculas depois da pontuação', 'Abreviaturas e pontuação'] },
    { n:'Ponto de interrogação', a:'?',
      d:'Marca a pergunta direta — a que se faz em voz alta, com entoação interrogativa. Também fecha a frase, por isso o que vem depois começa, em regra, com maiúscula.',
      u:'Coloque-o no fim da pergunta, colado à última palavra. Numa pergunta encaixada numa frase maior, fica no fim da parte interrogativa. Em diálogo, mantém-se mesmo quando a fala é seguida de um verbo declarativo: «— Vens? — perguntou ela.». As perguntas retóricas também o levam.',
      c:'A pergunta indireta («Perguntou se vinha.») não leva ponto de interrogação. Ao contrário do espanhol, em português não há ponto de interrogação invertido no início. Dois ou três seguidos («???») só em registo muito informal.',
      x:['Direta: «Quem deixou a luz acesa?»', 'Indireta, sem sinal: «Quis saber quem tinha deixado a luz acesa.»', 'Em diálogo: «— Já chegaram? — perguntou, sem levantar os olhos.»', 'Retórica: «Quem nunca mentiu para se poupar a uma discussão?»'],
      s:['Interrogação retórica', 'Pontuação do diálogo com travessão', 'Combinações de sinais'] },
    { n:'Ponto de exclamação', a:'!',
      d:'Marca a frase exclamativa e a interjeição: surpresa, alegria, dor, ordem, chamamento, espanto. Tal como o de interrogação, fecha a frase.',
      u:'Use-o depois de interjeições («Ai!», «Oh!»), de ordens ditas com força («Sai daqui!») e de frases em que a emoção é o próprio conteúdo. Em prosa narrativa, funciona melhor dentro das falas do que na voz do narrador. Depois de uma interjeição isolada, pode continuar-se com minúscula quando a frase segue: «Ah! que alívio» — mas a maiúscula é hoje o mais comum.',
      c:'É o sinal que mais se gasta. Um texto com muitas exclamações cansa e soa juvenil; a força tem de estar nas palavras. «!!!» e «?!» repetidos não são norma. Em textos formais e técnicos, quase nunca se usa.',
      x:['Interjeição: «— Ai! Queimei-me.»', 'Ordem: «— Larga isso!»', 'Excesso: «Estava tão feliz!!! Nem acreditava!» — melhor: «Estava feliz ao ponto de não acreditar.»'],
      s:['Pontuação expressiva', 'Combinações de sinais', 'Erros frequentes de pontuação'] },
    { n:'Reticências', a:'… · três pontos',
      d:'Três pontos seguidos (não mais) que marcam uma suspensão: pensamento interrompido, hesitação, insinuação, emoção que corta a fala, enumeração deixada em aberto, ou um corte numa citação (entre parênteses retos).',
      u:'Escrevem-se coladas à última palavra e seguidas de espaço. Se a frase termina com elas, não se acrescenta ponto final; a palavra seguinte começa com maiúscula se for nova frase, com minúscula se a frase continuar. Em diálogo, as reticências indicam que quem fala hesita ou se cala por si; o travessão no fim indica que foi interrompido por outro. Podem combinar-se com ponto de interrogação ou de exclamação: normalmente o sinal da frase vem primeiro («?…», «!…»); «…?» marca a hesitação antes da pergunta («E tu…?»).',
      c:'Não são quatro nem cinco pontos, nem «. . .» com espaços. Não substituem o «etc.» em textos formais, nem se juntam a ele («etc.…»). Usadas em excesso, dão um ar vago e sentimental ao texto — a insinuação perde força quando está em todas as frases.',
      x:['Hesitação: «— Eu… não sei se devia dizer-te isto.»', 'Suspensão da frase: «Se ele soubesse…»', 'Continuação com minúscula: «Ficou a pensar… e depois esqueceu.»', 'Com pergunta: «— E agora?…»', 'Corte numa citação: «Era uma vez [...] um rei sem reino.»'],
      t:'Numa Cena em que uma personagem esconde algo, as reticências nas falas dela — e só nas dela — podem ser o sinal para o leitor. Registe a escolha numa Nota associada à Personagem para manter a coerência.',
      s:['Reticência', 'Falas interrompidas e hesitações', 'Citações e transcrições', 'Combinações de sinais'] },
    { n:'Combinações de sinais', a:'?! · ?… · !… · sinais repetidos',
      d:'Alguns sinais juntam-se para somar valores: pergunta com espanto («?!»), pergunta que fica no ar («?…»), exclamação que se prolonga («!…»).',
      u:'Em regra, primeiro o sinal da frase (interrogação ou exclamação), depois as reticências; a ordem inversa («…?») mostra uma hesitação antes da pergunta. A combinação de interrogação e exclamação faz-se com um de cada, normalmente «?!». Depois de qualquer destes sinais não se põe ponto final, nem vírgula antes de um travessão de diálogo.',
      c:'Repetir o mesmo sinal («!!!», «???») é marca de registo informal (mensagens, banda desenhada) e não pertence à prosa cuidada. O sinal combinado «‽» (interrobang) não é usado em português.',
      x:['Espanto: «— Vendeste a casa?!»', 'Pergunta suspensa: «— Vens comigo?…»', 'Errado: — Vens?. — disse ela. / Certo: — Vens? — disse ela.'],
      s:['Ponto de interrogação', 'Ponto de exclamação', 'Reticências'] }
  ]},

  { name:'Vírgula', items:[
    { n:'Vírgula: princípios', a:'A pausa breve e a organização da frase',
      d:'A vírgula marca a pausa mais breve e, sobretudo, a organização da frase: separa o que está em série, isola o que está intercalado ou deslocado, e nunca separa o que está unido pela gramática. É o sinal mais usado e o mais discutido.',
      u:'Pense em quatro situações. 1) Enumeração: separa elementos da mesma função («maçãs, peras e laranjas»). 2) Intercalação: isola o que se mete no meio da frase (apostos, orações explicativas, incisos, vocativos). 3) Deslocação: separa o que sai do seu lugar habitual, sobretudo o que vem antes do sujeito («Ao fim da tarde, a vila esvaziou.»). 4) Coordenação: separa orações coordenadas sem conjunção, e as adversativas, explicativas e conclusivas. Quando hesitar, leia em voz alta: a pausa natural ajuda, mas não decide sozinha.',
      c:'A regra mais importante é negativa: não se põe vírgula entre o sujeito e o verbo, nem entre o verbo e os seus complementos (ver «Vírgula: quando não usar»). Não confunda pausa de respiração com vírgula — há pausas que não se escrevem e vírgulas que não se dizem.',
      x:['Enumeração: «Trouxe o caderno, a caneta e o livro.»', 'Intercalação: «O Duarte, que nunca chegava a horas, apareceu cedo.»', 'Deslocação: «Naquela casa, ninguém falava do pai.»', 'Coordenação sem conjunção: «Chegou, sentou-se, não disse nada.»'],
      s:['Vírgula: quando não usar', 'Vírgula com conjunções', 'Vírgula e orações relativas', 'Vírgula em intercalações, apostos e vocativos', 'Ritmo da frase'] },
    { n:'Vírgula: quando não usar', a:'Sujeito e verbo · verbo e complementos',
      d:'A vírgula não separa termos ligados diretamente pela gramática: o sujeito do predicado, o verbo dos seus complementos diretos e indiretos, o nome do seu complemento, nem a oração subordinante da completiva que dela depende.',
      u:'Antes de pôr uma vírgula, pergunte se ela separa duas coisas que precisam uma da outra. «Os homens que tinham vindo do norte, ficaram no cais» — a vírgula corta o sujeito do verbo: retire-a. Quando um sujeito longo dá vontade de respirar, reformule a frase em vez de pôr vírgula. As exceções são intercalações: se algo se mete entre o sujeito e o verbo, leva vírgula antes e depois («O médico, aliás, já sabia.»).',
      c:'É o erro de pontuação mais frequente, e o que mais denuncia um texto pouco revisto. Também é erro a vírgula antes de uma oração completiva introduzida por «que»: «Disse, que viria» → «Disse que viria». Alguns gramáticos admitem a vírgula depois de um sujeito muito longo, sobretudo se terminar num verbo, para evitar ambiguidade — mas é exceção a justificar, não regra.',
      x:['Errado: «A mulher do farol, nunca saía de casa.» / Certo: «A mulher do farol nunca saía de casa.»', 'Errado: «Deu ao filho, a chave.» / Certo: «Deu ao filho a chave.»', 'Errado: «Percebeu, que estava sozinho.» / Certo: «Percebeu que estava sozinho.»', 'Intercalação permitida: «A mulher do farol, dizia-se, nunca saía de casa.»'],
      s:['Vírgula: princípios', 'Erros frequentes de pontuação'] },
    { n:'Vírgula com conjunções', a:'e · nem · ou · mas · porém · pois · portanto · porque',
      d:'Cada conjunção tem o seu comportamento. As copulativas («e», «nem») e as disjuntivas («ou») dispensam vírgula quando ligam termos ou orações com o mesmo sujeito. As adversativas («mas», «porém», «contudo», «todavia», «no entanto»), as conclusivas («portanto», «logo», «por isso», «pois» depois do verbo) e as explicativas levam vírgula.',
      u:'«E»: sem vírgula em regra; com vírgula quando liga orações com sujeitos diferentes e a falta dela criaria ambiguidade («O cão mordeu o carteiro, e a vizinha gritou»), quando se repete para dar ênfase («e chorou, e gritou, e partiu»), ou quando tem valor adversativo («Prometeu, e não cumpriu»). «Mas»: vírgula antes, sempre que introduz uma oração. «Porém», «contudo», «todavia», «no entanto», «portanto»: no início da oração, vírgula antes; deslocados para o meio, entre vírgulas («Era tarde; ele, porém, continuou.»). «Pois»: explicativo, no início da oração, sem vírgula depois («Saiu cedo, pois tinha medo do trânsito»); conclusivo, depois do verbo e entre vírgulas («Não vens? Fico, pois, sozinho.»). «Porque» causal: vírgula quando a causa é um acrescento, sem vírgula quando é a informação principal.',
      c:'Não se põe vírgula depois de «mas» («Mas, ele veio» → «Mas ele veio»), a não ser que comece aí uma intercalação («Mas, quando chegou, já era tarde»). Quando liga termos, a vírgula antes de «mas» é facultativa («pobre mas honrado» ou «pobre, mas honrado»). Uma vírgula antes de «e» que ligue dois termos simples é erro: «pão, e manteiga».',
      x:['«Chegou cedo e saiu tarde.» (mesmo sujeito, sem vírgula)', '«A mãe dormia, e o pai lia na cozinha.» (sujeitos diferentes, com vírgula para clareza)', '«Queria ficar, mas tinha de ir.»', '«Estava cansado. Continuou, no entanto, a escrever.»', '«Não comas isso, porque está estragado.» / «Não fui porque estava doente.»'],
      s:['Vírgula: princípios', 'Ponto e vírgula', 'Parataxe e hipotaxe', 'Polissíndeto'] },
    { n:'Vírgula e orações relativas', a:'Restritivas e explicativas',
      d:'As orações introduzidas por «que», «o qual», «onde», «cujo» podem restringir o nome (dizer de qual se trata) ou explicá-lo (acrescentar uma informação sobre algo já identificado). A vírgula é o que as distingue — e muda o sentido da frase.',
      u:'Restritiva, sem vírgulas: «Os passageiros que tinham bilhete entraram.» (só esses entraram). Explicativa, entre vírgulas: «Os passageiros, que tinham bilhete, entraram.» (todos tinham bilhete, e todos entraram). Teste: se puder retirar a oração sem que a frase deixe de identificar aquilo de que fala, é explicativa e leva vírgulas.',
      c:'Uma vírgula a mais ou a menos muda o que se afirma. Com nomes próprios e coisas únicas, a relativa é quase sempre explicativa: «Lisboa, que fica junto ao Tejo, …». Não se esqueça da segunda vírgula quando a explicativa está no meio da frase.',
      x:['Restritiva: «O irmão que vive em Paris telefonou.» (há mais irmãos)', 'Explicativa: «O irmão, que vive em Paris, telefonou.» (só há um irmão, ou já se sabe de qual se fala)', 'Nome próprio: «A Inês, que detestava despedidas, saiu sem dizer nada.»'],
      s:['Vírgula: princípios', 'Vírgula em intercalações, apostos e vocativos', 'Ambiguidade'] },
    { n:'Vírgula em intercalações, apostos e vocativos', a:'Inciso · aposto · vocativo · advérbios e expressões de ligação',
      d:'Tudo o que se mete no meio da frase sem pertencer à sua estrutura vai entre vírgulas: o aposto («o Tomás, o faroleiro, …»), o vocativo (o nome de quem se chama), as orações e expressões intercaladas («dizia ele», «segundo consta»), e as expressões de ligação («isto é», «por exemplo», «aliás», «ou seja», «de facto», «no entanto» deslocado).',
      u:'Abra e feche: a vírgula de entrada tem sempre a sua vírgula de saída, a não ser que a intercalação esteja no início ou no fim da frase. O vocativo é separado em qualquer posição: «Pedro, anda cá.», «Anda cá, Pedro.», «Anda, Pedro, que é tarde.». Se o inciso for longo ou com outras vírgulas dentro, prefira travessões ou parênteses.',
      c:'Sem vírgula, o vocativo pode virar complemento: «Vamos comer, Pedro.» (chama-se o Pedro) / «Vamos comer Pedro.» (o Pedro é o almoço). Compare também «Ó Pedro, anda cá» (vocativo, com «ó») e «O Pedro anda cá» (afirmação). O esquecimento da vírgula de fecho é o erro mais comum nos incisos: «O relatório, segundo o diretor está pronto.»',
      x:['Aposto: «O Tomás, o faroleiro, nunca saía antes de escurecer.»', 'Vocativo: «— Avó, abre a porta!»', 'Expressão de ligação: «O plano, isto é, o que restava dele, ruiu.»', 'Inciso: «A casa, ao que parece, estava vazia há anos.»'],
      s:['Inciso e parêntese', 'Travessão (incisos)', 'Parênteses', 'Apóstrofe'] },
    { n:'Vírgula com gerúndio e particípio', a:'Orações reduzidas · «Abrindo a porta, …» · «Terminado o jantar, …»',
      d:'As orações de gerúndio e de particípio (chamadas reduzidas) funcionam como orações adverbiais: dizem quando, como, porquê ou em que condição. Separam-se por vírgula quando vêm antes da oração principal ou quando estão intercaladas.',
      u:'«Abrindo a porta, viu o mar.» / «Terminado o jantar, saíram para a varanda.» / «A avó, sentindo frio, fechou a janela.». No fim da frase, a vírgula depende da ligação: «Saiu batendo com a porta.» (o modo de sair, sem vírgula) / «Saiu, deixando a porta aberta.» (um acrescento, com vírgula).',
      c:'O sujeito do gerúndio antecipado deve ser o mesmo da oração principal: «Chegando a casa, o telefone tocou» sugere que foi o telefone a chegar. Em português europeu, o gerúndio é menos frequente do que no Brasil («estava lendo» → «estava a ler»): não o use por decalque.',
      x:['«Chegando ao cais, viu que o barco já tinha partido.»', '«Acabadas as aulas, a vila voltou ao silêncio.»', 'Ambíguo: «Saindo de casa, a chuva começou.» → «Quando saiu de casa, começou a chover.»'],
      s:['Vírgula com orações subordinadas e adverbiais', 'Vírgula: princípios'] },
    { n:'Vírgula com orações subordinadas e adverbiais', a:'Ordem da frase · deslocação · complementos circunstanciais',
      d:'As orações subordinadas adverbiais (de tempo, condição, causa, concessão…) e os complementos circunstanciais (de lugar, de tempo, de modo) separam-se por vírgula quando vêm antes da oração principal ou quando se intercalam. No fim da frase, na ordem habitual, a vírgula é facultativa.',
      u:'Antecipada: «Quando a maré baixou, foram ao cais.» Na ordem direta: «Foram ao cais quando a maré baixou.» (sem vírgula, o mais comum). Complementos curtos à cabeça podem dispensar a vírgula («Ontem choveu»); os longos pedem-na («Na manhã em que o farol se apagou, ninguém foi à pesca.»). As concessivas («embora», «ainda que») levam vírgula quase sempre.',
      c:'Uma vírgula a separar uma subordinada no fim da frase muda a ênfase: «Não saio, se chover» insiste na condição como acrescento. Use-a por intenção, não por hábito.',
      x:['«Se o vires, diz-lhe que liguei.»', '«Diz-lhe que liguei se o vires.»', '«Embora estivesse cansada, continuou a escrever.»', '«Ao chegar ao cimo da colina, viu o mar.»'],
      s:['Vírgula: princípios', 'Frase periódica e frase cumulativa', 'Ênfase e fim de frase'] }
  ]},

  { name:'Ponto e vírgula e dois pontos', items:[
    { n:'Ponto e vírgula', a:'; · pausa intermédia (sem hífen, desde o Acordo de 1990; antes «ponto-e-vírgula»)',
      d:'Marca uma pausa maior do que a vírgula e menor do que o ponto. Separa partes de uma frase que têm autonomia mas pertencem ao mesmo pensamento, e organiza enumerações complexas.',
      u:'Use-o: 1) entre orações coordenadas extensas, sobretudo se já tiverem vírgulas dentro («O pai, cansado, adormeceu no sofá; a mãe, inquieta, ficou à janela até tarde.»); 2) entre orações em contraste ou paralelismo, sem conjunção («Uns partiam; outros ficavam.»); 3) antes de conectores como «porém», «contudo», «no entanto», «por isso» quando ligam orações longas; 4) para separar elementos de uma enumeração que já têm vírgulas, ou os itens de uma lista em alíneas. A seguir vem minúscula.',
      c:'Não serve para introduzir nada (isso é trabalho dos dois pontos) nem para separar o sujeito do verbo. Com orações curtas, a vírgula é preferível. Usado com conta, dá ao texto um ritmo pensado; usado em todas as frases, torna-o rígido e antiquado.',
      x:['Contraste: «Na cidade, ninguém o conhecia; na aldeia, todos sabiam o nome do pai.»', 'Enumeração com vírgulas: «Estavam lá o Tomás, o faroleiro; a Celeste, a avó; e o Duarte, que ninguém convidara.»', 'Com conector: «Fez tudo o que lhe pediram; no entanto, ninguém lhe agradeceu.»'],
      t:'Na sinopse de um Tomo ou no resumo de uma Cena, o ponto e vírgula ajuda a pôr lado a lado acontecimentos paralelos sem os transformar numa lista.',
      s:['Vírgula com conjunções', 'Enumerações e listas', 'Paralelismo', 'Parataxe e hipotaxe'] },
    { n:'Dois pontos', a:': (sem hífen em Portugal, desde o Acordo de 1990; no Brasil, «dois-pontos»)',
      d:'Anunciam: o que vem a seguir explica, concretiza, enumera, conclui ou cita o que veio antes. São uma seta para a frente.',
      u:'Use-os para introduzir: 1) uma enumeração («Levou três coisas: o mapa, a lanterna e a carta.»); 2) uma explicação ou consequência («Percebeu tudo: a carta nunca tinha sido enviada.»); 3) uma citação entre aspas («Ela disse: «Não volto.»») ou uma fala, que passa para a linha seguinte com travessão (nunca na mesma linha dos dois pontos); 4) um exemplo. Depois dos dois pontos, minúscula — mesmo antes de uma frase completa; maiúscula só numa citação, numa fala, num nome próprio ou em itens em linhas próprias.',
      c:'Não se põem entre um verbo e o seu complemento quando nada se anuncia: «Os ingredientes são: farinha e ovos» → «Os ingredientes são farinha e ovos» (ou «Os ingredientes: farinha e ovos.»). Evite usar dois pontos duas vezes na mesma frase. Ao contrário do francês, não levam espaço antes.',
      x:['Enumeração: «Só lhe restavam duas saídas: mentir ou partir.»', 'Explicação: «Ninguém dormiu: o farol estava apagado.»', 'Citação: Escreveu no diário: «Hoje vi o mar pela última vez.»', 'Errado: «Ele trouxe: pão e vinho.»'],
      s:['Enumerações e listas', 'Citações e transcrições', 'Discurso direto', 'Maiúsculas depois da pontuação'] }
  ]},

  { name:'Inserir, destacar e citar', items:[
    { n:'Travessão (incisos)', a:'— · risca · travessões em par',
      d:'Fora do diálogo, o travessão isola uma intercalação — explicação, comentário, aparte — com mais força do que a vírgula e mais à vista do que os parênteses. Também pode marcar, sozinho, uma conclusão ou um desvio brusco no fim da frase.',
      u:'Em pares, para intercalar: «A vila — se é que se podia chamar vila àquilo — tinha doze casas.» Sozinho, para destacar o que vem no fim: «Havia uma única explicação — e ninguém a queria ouvir.» Em português europeu, o travessão escreve-se com espaço antes e depois. Se o inciso acabar onde acaba a frase, o segundo travessão desaparece e fica só o ponto final. Quando o inciso coincide com um lugar onde haveria vírgula, essa vírgula vai depois do segundo travessão.',
      c:'Não use o hífen (-) em vez do travessão (—): são sinais diferentes. Muitos travessões na mesma página dão um texto aos solavancos; reserve-os para o que deve saltar à vista. Não se usa travessão entre o sujeito e o verbo sem nada intercalado.',
      x:['Inciso: «O farol — apagado há vinte anos — acendeu-se naquela noite.»', 'Remate: «Só faltava uma coisa — coragem.»', 'Com vírgula a seguir: «Quando chegou — já de noite —, a casa estava fechada.»'],
      s:['Inciso e parêntese', 'Hífen, meia-risca e travessão', 'Parênteses', 'Pontuação do diálogo com travessão'] },
    { n:'Parênteses', a:'( ) · parênteses curvos',
      d:'Isolam uma informação acessória: um esclarecimento, uma data, uma tradução, uma sigla, um comentário em surdina. O que está entre parênteses pode ser saltado sem que a frase perca o sentido.',
      u:'A pontuação da frase principal fica fora dos parênteses: «Chegou em 1974 (ou talvez em 1975).». Se o parêntese é uma frase completa e independente, a sua pontuação fica dentro: «Saiu. (Ninguém o viu sair.)». Antes de abrir parênteses, não se põe vírgula; se a frase a pedir, ela vai depois de os fechar. Em narrativa, os parênteses dão um tom de aparte, de confidência ou de ironia do narrador.',
      c:'Parênteses dentro de parênteses confundem: use parênteses retos no nível interior, ou reformule. Um texto cheio de parênteses parece hesitante, como se o autor não soubesse o que é principal. A diferença face ao travessão: os parênteses baixam a voz, os travessões levantam-na.',
      x:['Esclarecimento: «A APA (Agência Portuguesa do Ambiente) emitiu um aviso.»', 'Aparte do narrador: «A avó (que nunca se enganava em nada) disse que ia chover.»', 'Frase independente: «Fechou a porta à chave. (Fazia-o sempre, desde o assalto.)»'],
      s:['Inciso e parêntese', 'Travessão (incisos)', 'Parênteses retos', 'Narrador intruso (comentador)'] },
    { n:'Parênteses retos', a:'[ ] · colchetes (no Brasil)',
      d:'Servem sobretudo dentro de citações, para marcar o que não é do autor citado: cortes, acrescentos, correções, comentários. Também substituem os parênteses curvos dentro de outros parênteses.',
      u:'Corte numa citação: «[...]» (ou «[…]»). Acrescento para esclarecer: «Ela [a mãe] nunca respondeu.». Erro no original, mantido de propósito: «[sic]» logo a seguir. Destaque acrescentado: «[sublinhado nosso]». Parêntese dentro de parêntese: «(ver o capítulo 3 [edição de 1999])».',
      c:'Prefira os parênteses retos, sobretudo em textos rigorosos: os curvos «(…)» são frequentes, na imprensa e em livros, mas ambíguos — o leitor pode não saber o que é do autor e o que é seu. «[sic]» usado para troçar de quem se cita é deselegante.',
      x:['O narrador garante que «a casa [...] nunca teve dono».', 'Escreveu que «ele [o faroleiro] sabia de tudo».', 'A carta dizia: «Espero que estejas bom e bem desposto [sic].»'],
      s:['Citações e transcrições', 'Parênteses', 'Reticências'] },
    { n:'Aspas', a:'« » · “ ” · ‘ ’ · aspas angulares, curvas e simples',
      d:'Delimitam citações, falas (em alternativa ao travessão), títulos de partes de obras, palavras estrangeiras, termos usados com sentido especial ou irónico, e palavras referidas como palavras. Em Portugal, a forma tradicional e preferida pelas editoras são as aspas angulares « », também chamadas aspas francesas.',
      u:'Hierarquia: « » no primeiro nível, “ ” numa citação dentro de outra, ‘ ’ num terceiro nível, raro. As aspas angulares escrevem-se coladas ao texto, sem espaços por dentro (ao contrário do francês). Pontuação: se o sinal pertence ao que está citado, fica dentro das aspas; se pertence à frase que o enquadra, fica fora. Uma citação completa e autónoma, introduzida por dois pontos, termina com o seu próprio sinal dentro das aspas, sem outro ponto depois. Títulos: aspas para capítulos, contos, poemas e artigos; itálico para livros, jornais e filmes (na prática, muitas editoras usam itálico para tudo).',
      c:'Não use aspas para dar ênfase («produtos “frescos”» sugere que não o são). Escolha um sistema — angulares ou curvas — e mantenha-o em todo o livro. As aspas retas do teclado (" ") são uma solução de máquina de escrever; num manuscrito final, substitua-as. A «vírgula dentro das aspas» à inglesa não é norma portuguesa.',
      x:['Três níveis: «O chefe disse: “Quando ouvir a palavra ‘relatório’, finja que trabalha.”»', 'Pontuação dentro (o sinal é da citação): Perguntou: «Vens?»', 'Pontuação fora (o sinal é da frase): Chamava-lhe «a casa velha».', 'Ironia: O «amigo» dele nunca mais apareceu.', 'Título de conto: Li «O Defunto», de Eça de Queirós, numa tarde.'],
      t:'Defina o sistema de aspas e de diálogo do projeto numa Nota associada ao Tomo, antes de começar: angulares ou curvas, travessão ou aspas nas falas, itálico para pensamentos. A coerência entre Tomos de uma série nota-se.',
      s:['Citações e transcrições', 'Diálogo com aspas', 'Itálico, negrito e maiúsculas de destaque', 'Ironia'] },
    { n:'Itálico, negrito e maiúsculas de destaque', a:'Recursos tipográficos de destaque',
      d:'Não são sinais de pontuação, mas fazem parte do mesmo sistema: dizem ao leitor que uma palavra tem estatuto especial. O itálico é o recurso literário por excelência; o negrito e as maiúsculas pertencem sobretudo aos textos técnicos e informativos.',
      u:'Itálico para: títulos de livros, jornais, filmes e obras de arte; palavras estrangeiras não aportuguesadas («um certo *savoir-faire*»); ênfase na fala («Eu *disse* que não»); pensamentos das personagens, se esse for o sistema escolhido; nomes de barcos. Num texto já em itálico, o destaque faz-se em redondo (texto normal).',
      c:'Ênfase em itálico a cada parágrafo é o equivalente escrito de falar aos gritos. Maiúsculas inteiras numa fala leem-se como gritos e cansam depressa. O negrito, em ficção, é quase sempre um erro. Num manuscrito para editora, assinale o itálico em itálico (não sublinhado), salvo instrução em contrário.',
      x:['Ênfase: «— Eu não *perdi* a chave. Alguém a tirou.»', 'Estrangeirismo: «Faltava-lhe *timing*, dizia o editor.»', 'Título: «Relia *Os Maias* todos os verões.»'],
      s:['Aspas', 'Pensamentos e discurso interior', 'Estrangeirismo', 'Recursos gráficos'] },
    { n:'Ó, oh e outras interjeições', a:'Vocativo com «ó» · interjeição «oh» · «ah», «ai», «olá»',
      d:'«Ó» (com acento) acompanha o vocativo: chama alguém. «Oh» (com h) é uma interjeição de espanto, dor, desejo. São palavras diferentes e pontuam-se de forma diferente.',
      u:'Vocativo: «Ó Pedro, anda cá!» — o «ó» junta-se ao nome, sem vírgula entre os dois, e o vocativo separa-se do resto por vírgula. Interjeição: «Oh! Que pena.», ou, ligada ao resto da frase, «Oh, que pena!». Outras interjeições («Ah», «Ai», «Olá», «Ui») seguem o mesmo modelo: ponto de exclamação se ficam sozinhas; vírgula se se ligam à frase.',
      c:'«Oh Pedro» por «Ó Pedro» é um erro frequente. Não ponha vírgula entre «ó» e o nome («Ó, Pedro» está errado).',
      x:['«— Ó mãe, onde está a chave?»', '«— Oh, não! Esqueci-me outra vez.»', '«— Ai, que susto!»'],
      s:['Vírgula em intercalações, apostos e vocativos', 'Ponto de exclamação', 'Apóstrofe'] },
    { n:'Apóstrofo, barra e asterisco', a:'’ · / · *',
      d:'Sinais auxiliares. O apóstrofo marca a supressão de letras na representação da fala ou em formas poéticas («’tá», «Sant’Ana»). A barra separa alternativas, datas abreviadas, frações e versos citados em linha. O asterisco remete para notas ou, em sequência, marca uma quebra de cena.',
      u:'Apóstrofo para reproduzir a oralidade com moderação («— ’Tá bem, ’tá bem.»), e nas formas previstas no Acordo («Sant’Ana», «Nun’Álvares», «d’Os Lusíadas», «galinha-d’angola»). Barra: «e/ou», «km/h», «21/11/2026», e para separar versos citados dentro de um parágrafo («Valeu a pena? Tudo vale a pena / Se a alma não é pequena»). Um asterisco centrado — ou três (* * *) — numa linha em branco indica uma mudança de cena dentro do capítulo.',
      c:'Muitos apóstrofos para imitar a pronúncia tornam a leitura penosa e podem ridicularizar as personagens; sugira a oralidade pelo léxico e pela sintaxe. «E/ou» é burocrático em ficção. Use sempre o apóstrofo curvo (’), não o reto (\').',
      x:['Oralidade: «— Atão, ’tás bom?»', 'Versos em linha (Pessoa, «Mar Português»): «Tudo vale a pena / Se a alma não é pequena» — os versos mantêm a maiúscula inicial do original.', 'Quebra de cena: uma linha só com «* * *».'],
      s:['Idioleto e marcas de oralidade', 'Parágrafo e espaço em branco', 'Elipse narrativa'] }
  ]},

  { name:'Pontuação do diálogo', items:[
    { n:'Pontuação do diálogo com travessão', a:'Norma editorial portuguesa · a fala, o inciso, a mudança de linha',
      d:'Em Portugal, o diálogo escreve-se tradicionalmente com travessão: cada fala começa numa nova linha, com um travessão seguido de espaço. As intervenções do narrador dentro ou depois da fala também se separam por travessão.',
      u:'1) Cada mudança de interlocutor abre um parágrafo novo com «— ». 2) Fala seguida de verbo declarativo: o travessão separa a fala do narrador e o verbo começa com minúscula; a fala não leva ponto final, mas mantém «?», «!» ou «…» se os tiver: «— Não venhas — disse ela.»; «— Vens? — perguntou ela.». 3) Narrador no meio da fala: dois travessões, e a fala continua: «— Não sei — disse ela —, talvez amanhã.» (a vírgula da fala vai depois do segundo travessão). 4) Se a fala continua com nova frase depois do inciso, o inciso fecha com ponto: «— Não venhas — disse ela. — Hoje não.». 5) Se a fala é seguida de uma ação (não de um verbo de dizer), a fala fecha com ponto e a ação começa com maiúscula: na mesma linha, separada por travessão («— Não venhas. — Fechou a porta.»); ou num parágrafo novo, sem travessão.',
      c:'Não troque o travessão (—) pelo hífen (-). Não ponha ponto final antes do travessão que introduz o verbo declarativo («— Não venhas. — disse ela.» está errado). Não misture travessões e aspas para falas no mesmo livro. Uma fala longa que ocupa vários parágrafos repete o travessão no início de cada um — confirme que o contexto deixa claro que continua a mesma personagem (alguns editores preferem reduzir a fala a um parágrafo). Algumas editoras admitem vírgula em vez do segundo travessão («— Não venhas, disse ela.»), herança de outras tradições; a forma com travessão é a mais corrente hoje.',
      x:['Verbo declarativo: — Já é tarde — disse a avó.', 'Pergunta: — Quem está aí? — perguntou Inês.', 'Inciso a meio: — Se quiseres — murmurou ele —, levo-te ao farol.', 'Nova frase depois do inciso: — Não demoro — disse Tomás. — Esperem por mim.', 'Ação na mesma linha: — Não demoro. — Tomás vestiu o casaco e saiu.'],
      t:'Na ficha de uma Cena, o resumo não precisa de diálogo — mas, se citar uma fala-chave, use o mesmo sistema do manuscrito para que a Cena e o texto final batam certo.',
      s:['Discurso direto', 'Verbos declarativos e gestos de cena', 'Hífen, meia-risca e travessão', 'Falas interrompidas e hesitações', 'Diálogo com aspas'] },
    { n:'Diálogo com aspas', a:'« » ou “ ” nas falas · tradição inglesa e alguma edição contemporânea',
      d:'Em vez do travessão, as falas podem vir entre aspas, dentro do parágrafo do narrador. É a norma em inglês e usa-se em algumas traduções e em autores portugueses contemporâneos.',
      u:'A fala fica entre aspas; o verbo declarativo vem fora, separado por vírgula: «Não venhas», disse ela. Se a fala é pergunta ou exclamação, o sinal fica dentro das aspas e a vírgula mantém-se depois delas: «Vens?», perguntou. Quando a fala fecha a frase, o ponto fica fora ou dentro conforme o sistema da editora; o mais comum em Portugal é fora, se a fala não for uma frase completa citada. Cada mudança de interlocutor continua a pedir um parágrafo novo.',
      c:'Decida de início e não misture com travessões. Em português, as aspas no diálogo dão um ar de tradução; ponha-o ao serviço do livro (um narrador que relata falas de outros, um registo mais distante). Nas aspas angulares, evite dois níveis de « » seguidos: uma citação dentro da fala passa a “ ”.',
      x:['«Não venhas», disse ela, sem se virar.', '«Vens?», perguntou ele.', '«Disseste “nunca”», lembrou-lhe a avó, «e afinal voltaste.»'],
      s:['Aspas', 'Pontuação do diálogo com travessão', 'Discurso direto'] },
    { n:'Diálogo sem marcas', a:'Falas integradas no parágrafo · vírgula e maiúscula · à maneira de Saramago',
      d:'Alguns autores dispensam travessões e aspas: as falas correm dentro do parágrafo, separadas apenas por vírgulas e marcadas por uma maiúscula no início de cada fala. José Saramago tornou este processo célebre; Cormac McCarthy, em inglês, escreve sem aspas.',
      u:'Funciona quando a voz do narrador e as das personagens se querem misturadas, num fluxo contínuo, quase oral — como se tudo fosse contado de uma vez. Mantenha marcas mínimas e constantes: no estilo de Saramago, a maiúscula a seguir à vírgula indica que começa uma fala, e o verbo declarativo identifica quem fala. Teste em voz alta: o leitor tem de saber sempre quem está a falar.',
      c:'É uma escolha de estilo que pede muito domínio: sem ritmo e sem identificação clara das vozes, o leitor perde-se. Não é ausência de pontuação, é outra pontuação — tem regras e tem de ser coerente do princípio ao fim do livro.',
      x:['Estilo de Saramago (frase criada): «Perguntou ela, Vens amanhã, e ele respondeu, Não sei, talvez, e ficaram os dois calados a olhar para o mar.»', 'Ver *Ensaio sobre a Cegueira* e *O Evangelho segundo Jesus Cristo*, de Saramago, e *A Estrada*, de McCarthy.'],
      s:['Discurso direto livre', 'Pontuação expressiva', 'Estilo oral', 'Fluxo de consciência'] },
    { n:'Dois pontos antes de uma fala', a:'«Ela disse:» e a fala na linha seguinte',
      d:'Quando o narrador anuncia uma fala com um verbo declarativo e dois pontos, a fala passa para a linha seguinte, em parágrafo próprio, com travessão. Nunca se escreve o travessão na mesma linha dos dois pontos.',
      u:'Narrador: «A avó olhou para todos e disse:» — linha seguinte: «— Ninguém sai desta casa.». É a forma mais solene de introduzir uma fala; para a maioria das falas, o verbo declarativo depois da fala («— Ninguém sai — disse a avó.») é mais leve. Com aspas, a fala pode ficar na mesma linha: «A avó disse: «Ninguém sai desta casa.»».',
      c:'«Ela disse: — Não volto.» na mesma linha é um erro frequente. Muitos «disse:» seguidos tornam o diálogo pesado e antiquado.',
      x:['A avó levantou-se e disse: (nova linha) — Ninguém sai desta casa.', 'Com aspas, na mesma linha: A avó disse: «Ninguém sai desta casa.»'],
      s:['Dois pontos', 'Pontuação do diálogo com travessão', 'Verbos declarativos e gestos de cena'] },
    { n:'Falas seguidas da mesma personagem', a:'Nova fala ou continuação? · pausa dentro da fala',
      d:'Em diálogo com travessão, cada parágrafo com travessão é lido como uma mudança de interlocutor. Se a mesma personagem diz duas coisas separadas por uma ação ou por uma pausa, é preciso mostrá-lo.',
      u:'Pausa curta: mantenha tudo na mesma fala, com um inciso do narrador entre travessões: «— Não sei. — Olhou para o mar. — Talvez amanhã.». Pausa longa ou mudança de cena: um parágrafo de narração a identificar quem volta a falar («A avó ficou calada muito tempo. Depois:» e, na linha seguinte, a fala). Interrupção por outra personagem: travessão no fim da fala cortada e a fala de quem interrompe no parágrafo seguinte.',
      c:'Dois parágrafos seguidos com travessão, ambos da mesma personagem e sem nada entre eles, levam o leitor a atribuir o segundo à outra personagem.',
      x:['— Não sei. — Olhou para o mar. — Talvez amanhã.', 'Errado: duas linhas seguidas «— Não sei.» / «— Talvez amanhã.», ditas pela mesma pessoa.'],
      s:['Pontuação do diálogo com travessão', 'Falas interrompidas e hesitações'] },
    { n:'Falas interrompidas e hesitações', a:'Reticências ou travessão no fim da fala',
      d:'Uma fala pode ficar a meio de duas maneiras: quem fala hesita ou deixa a frase em suspenso (reticências), ou é cortado por outra pessoa ou por um acontecimento (travessão, em muitas editoras; reticências, noutras).',
      u:'Hesitação ou suspensão: «— Eu achava que tu…». Interrupção por outro: «— Eu achava que tu —» / «— Cala-te!». Retoma da fala interrompida: pode começar com reticências ou com minúscula, para mostrar que é a mesma frase: «— … que tu nunca mais voltavas.». Gaguez ou corte de palavra: hífen ou reticências na palavra cortada: «— N-não fui eu.».',
      c:'Escolha um sinal para a interrupção e mantenha-o. Não abuse das hesitações: duas ou três personagens que hesitam em todas as falas soam iguais. Gaguejar em todas as falas de uma personagem torna-se caricatura.',
      x:['Hesitação: — Se tu soubesses o que eu… (e, fora da fala:) Calou-se.', 'Interrupção: — Eu só queria — / — Já sei o que querias.', 'Gaguez: — Eu n-não… não fui eu.'],
      s:['Reticências', 'Pontuação do diálogo com travessão', 'Subtexto', 'Idioleto e marcas de oralidade'] },
    { n:'Pensamentos e discurso interior', a:'Itálico · aspas · discurso indireto livre · sem marcas',
      d:'Os pensamentos de uma personagem podem aparecer como fala interior direta (em itálico ou entre aspas), como discurso indireto («pensou que…») ou fundidos na voz do narrador (discurso indireto livre), sem marca nenhuma.',
      u:'Pensamento direto, na primeira pessoa e no presente: em itálico, sem aspas e sem travessão — *Não vou conseguir*, pensou. Indireto: «Pensou que não ia conseguir.». Indireto livre: «Não ia conseguir. Nunca tinha conseguido.» — a frase é do narrador, mas a voz é da personagem. Escolha um sistema e use-o em todo o livro.',
      c:'Não use travessão para pensamentos: o leitor lê-os como falas ditas em voz alta. Itálico em parágrafos inteiros cansa; para monólogos longos, o indireto livre é mais elegante. «Pensou para si mesmo» é redundante.',
      x:['Direto: *Já é tarde*, pensou Inês.', 'Indireto: «Inês pensou que já era tarde.»', 'Indireto livre: «Inês olhou para o relógio. Já era tarde. Tarde demais, como sempre.»'],
      s:['Discurso indireto livre', 'Monólogo interior', 'Itálico, negrito e maiúsculas de destaque', 'Fluxo de consciência'] },
    { n:'Citações dentro de uma fala', a:'Fala dentro de fala · cartas, mensagens, títulos',
      d:'Quando uma personagem cita outra pessoa, lê uma carta ou repete uma frase, há dois níveis de discurso que precisam de marcas diferentes.',
      u:'Com diálogo em travessão, a fala citada vai entre aspas angulares: — E ela disse-me: «Não voltes cá.» Com diálogo em aspas: o nível interior passa às aspas curvas — «A tua mãe disse “nunca”», respondeu ele. Textos longos lidos em voz alta (uma carta, um bilhete) podem sair do diálogo e aparecer recolhidos, em parágrafo próprio, em itálico ou com outra mancha.',
      c:'Três níveis de aspas seguidos dificultam a leitura; reformule para discurso indireto quando puder. Mensagens de telemóvel e correios eletrónicos pedem um sistema gráfico próprio, coerente em todo o livro.',
      x:['Com travessão: — A tua avó disse-me: «Ele há de voltar.» E voltaste.', 'Com aspas: «A carta acabava assim: “Não me procures.”», leu ele.'],
      s:['Aspas', 'Epistolar / documental', 'Diálogo com aspas'] }
  ]},

  { name:'Traços, espaços e maiúsculas', items:[
    { n:'Hífen, meia-risca e travessão', a:'- · – · — · traço de união, meia-risca, risca',
      d:'São três sinais diferentes, de comprimentos diferentes. O hífen (-) é o mais curto e liga elementos de palavras: compostos («guarda-chuva»), pronomes («disse-lhe»), divisão silábica no fim da linha. A meia-risca (–) liga intervalos e extremos: «páginas 10–20», «1914–1918», «linha Lisboa–Porto» (muitas editoras usam aqui o hífen, que o Acordo indica para encadeamentos de palavras). O travessão (—) é o mais comprido e é pontuação: abre falas e isola incisos.',
      u:'No Windows: Alt + 0150 (–) e Alt + 0151 (—); no Mac: Option + hífen (–) e Option + Shift + hífen (—); em muitos processadores de texto, dois hífenes seguidos são substituídos automaticamente — mas, conforme haja espaços ou não, uns inserem o travessão e outros a meia-risca: confirme qual dos sinais o programa pôs. Hífen sem espaços; meia-risca sem espaços nos intervalos; travessão com espaços antes e depois (norma portuguesa).',
      c:'Escrever « - » com espaços em vez do travessão é o erro tipográfico mais frequente em manuscritos. Com o Acordo de 1990, muitas locuções perderam o hífen: «ponto e vírgula», «dois pontos», «fim de semana», «dia a dia».',
      x:['Hífen: «Deu-lhe o guarda-chuva.»', 'Meia-risca: «A guerra de 1914–1918.»', 'Travessão: «— Leva o guarda-chuva — disse a mãe.»'],
      s:['Travessão (incisos)', 'Pontuação do diálogo com travessão', 'Espaços e pontuação'] },
    { n:'Espaços e pontuação', a:'Onde há espaço, e onde não há',
      d:'Em português, os sinais de pontuação ficam colados à palavra anterior e são seguidos de um espaço. As exceções são os sinais que abrem (aspas, parênteses), que ficam colados à palavra seguinte, e o travessão, que tem espaço dos dois lados.',
      u:'Sem espaço antes de . , ; : ? ! … ) » ”. Sem espaço depois de ( « “. Um espaço (não dois) depois do ponto final. O travessão: espaço antes e depois, exceto no início de uma fala (só depois). Números: espaço, ou espaço fino, a separar os milhares («12 500»), vírgula nas décimas («3,5»).',
      c:'O espaço antes de «?», «!», «:» e «;» é regra francesa, não portuguesa. Dois espaços depois do ponto são hábito da máquina de escrever. Espaços por dentro de aspas e parênteses («( assim )») são erro.',
      x:['Certo: «Vens? Não sei: talvez.»', 'Errado: «Vens ? Não sei : talvez .»', 'Certo: (entre parênteses), «entre aspas». Errado: ( entre parênteses ), « entre aspas ».'],
      s:['Hífen, meia-risca e travessão', 'Números, datas e horas'] },
    { n:'Maiúsculas depois da pontuação', a:'Depois de ponto, de dois pontos, de interrogação e de exclamação',
      d:'Depois de ponto final, maiúscula sempre. Depois de interrogação, exclamação e reticências, maiúscula quando começa nova frase e minúscula quando a frase continua. Depois de dois pontos e de ponto e vírgula, minúscula em regra.',
      u:'«Ninguém respondeu. Ela voltou a bater.» / «Quem seria? ninguém sabia.» é antiquado; hoje escreve-se «Quem seria? Ninguém sabia.». Mas: «— Vens? — perguntou ela.» (o verbo declarativo continua a frase da fala, por isso minúscula). Depois de dois pontos: minúscula numa explicação, numa enumeração e mesmo antes de uma frase completa; maiúscula numa citação, numa fala, num nome próprio ou em itens em linhas próprias.',
      c:'Os dias da semana, os meses e as estações escrevem-se com minúscula (os meses e as estações por força do Acordo de 1990): «segunda-feira», «novembro», «inverno». Pontos cardeais com minúscula, exceto quando designam regiões («o Norte do país»).',
      x:['«Chegou tarde: o comboio atrasara-se.»', 'Citação depois de dois pontos, com maiúscula: Disse-lhe apenas: «Volta.»', '— Ainda aqui estás? — admirou-se ela.'],
      s:['Dois pontos', 'Ponto final', 'Pontuação do diálogo com travessão'] }
  ]},

  { name:'Listas, números e citações', items:[
    { n:'Enumerações e listas', a:'Séries na frase · listas com alíneas',
      d:'Dentro da frase, os elementos de uma enumeração separam-se por vírgulas e o último liga-se por «e», «ou» ou «nem», sem vírgula. Em listas com alíneas, cada item fica numa linha, pontuado de forma coerente.',
      u:'Na frase: «Comprou pão, leite e fruta.». Com itens complexos (com vírgulas lá dentro), separe-os por ponto e vírgula. Em listas: se os itens são palavras ou expressões curtas, minúscula e sem pontuação, ou com ponto e vírgula e ponto final no último; se cada item é uma frase completa, maiúscula e ponto final. O importante é a coerência dentro do mesmo texto.',
      c:'A «vírgula de Oxford» (vírgula antes do «e» final, à inglesa) não é norma portuguesa — só se usa para evitar ambiguidade. Dois pontos antes da enumeração só quando algo a anuncia.',
      x:['«Trouxe o mapa, a lanterna e a carta.»', 'Itens complexos: «Visitou Braga, no Minho; Viseu, na Beira; e Évora, no Alentejo.»', 'Lista de frases completas, uma por linha, cada uma com maiúscula e ponto final.'],
      s:['Ponto e vírgula', 'Dois pontos', 'Enumeração', 'Gradação'] },
    { n:'Números, datas e horas', a:'Algarismos ou extenso · vírgula decimal · horas',
      d:'Em ficção, os números escrevem-se de preferência por extenso, sobretudo nas falas e quando são pequenos ou redondos; em textos técnicos, em algarismos. As convenções portuguesas diferem das inglesas.',
      u:'Vírgula para as décimas («3,5 km»), espaço para os milhares («12 000»). Datas: «21 de novembro de 2026» (mês com minúscula), ou «21/11/2026», «21-11-2026». Horas: «às 14h30», «às 14:30» ou, em ficção, «às duas e meia da tarde». Localidade e data numa carta: «Lisboa, 21 de novembro de 2026».',
      c:'Evite começar uma frase com algarismos: escreva o número por extenso ou reformule. O ponto como separador decimal e a vírgula como separador de milhares são convenções inglesas. Em diálogo, os números ditos por extenso respeitam a fala: «— Paguei quarenta e cinco euros.».',
      x:['«O barco tinha vinte e dois metros.»', '«A temperatura desceu para 3,5 °C.»', '«Lisboa, 3 de março de 1974»'],
      s:['Espaços e pontuação', 'Abreviaturas e pontuação'] },
    { n:'Abreviaturas e pontuação', a:'Ponto abreviativo · siglas · etc.',
      d:'As abreviaturas levam ponto («Sr.», «Dr.ª», «pág.», «etc.»); as siglas e os símbolos não («ONU», «km», «kg»).',
      u:'Se a frase termina numa abreviatura, o ponto da abreviatura é também o ponto final. Antes de «etc.», vírgula: «laranjas, peras, etc.». Os símbolos de unidades não têm plural nem ponto («10 km», e não «10 kms.»).',
      c:'«Etc.» já inclui «e» («et cetera»): «e etc.» é redundante. Em ficção, sobretudo nas falas, evite abreviaturas: «— O senhor doutor está?» lê-se melhor do que «— O Sr. Dr. está?».',
      x:['«Comprou fruta, legumes, etc.»', '«A reunião é com a Dr.ª Marta.»', '«Andou 5 km a pé.»'],
      s:['Ponto final', 'Números, datas e horas'] },
    { n:'Notas de rodapé, títulos e epígrafes', a:'Chamada de nota · títulos de capítulo · epígrafe',
      d:'Elementos de paratexto com convenções próprias: a chamada de nota (o número que remete para o rodapé), os títulos (do livro, das partes, dos capítulos) e as epígrafes (a citação que abre um livro ou um capítulo).',
      u:'Chamada de nota: na tradição portuguesa, vai antes do sinal de pontuação («…como se sabe¹.»), embora muitas editoras a ponham depois. Títulos: sem ponto final; mantêm «?», «!» e «…» se fizerem parte do título. Epígrafe: a citação em linha própria, sem aspas, em itálico ou corpo menor, e o autor na linha seguinte, alinhado à direita, precedido de travessão («— Fernando Pessoa») ou sem ele.',
      c:'Coerência acima de tudo: o mesmo sistema de notas e de títulos em todo o livro. Em ficção, notas de rodapé são raras e chamam a atenção — use-as só quando são um recurso deliberado.',
      x:['Título de capítulo: «A noite em que o farol se apagou» (sem ponto).', 'Título com pergunta: «Quem acendeu a luz?»', 'Epígrafe: a citação numa linha; na seguinte, «— Sophia de Mello Breyner Andresen».'],
      s:['Título', 'Citações e transcrições', 'Primeira frase'] },
    { n:'Citações e transcrições', a:'Citar com rigor · pontuação dentro e fora · cortes',
      d:'Citar é reproduzir as palavras de outro exatamente como foram escritas. A pontuação tem de deixar claro onde começa e acaba a citação, o que foi cortado e o que foi acrescentado.',
      u:'Citação curta, dentro do parágrafo: entre aspas. Citação longa (mais de três ou quatro linhas): em bloco recolhido, sem aspas, com outro corpo de letra. Pontuação: o sinal fica dentro das aspas se pertencer ao texto citado, fora se pertencer à frase de quem cita. Cortes: «[...]». Acrescentos e esclarecimentos: entre parênteses retos. Erros do original: «[sic]». Indique sempre o autor e, em textos de não ficção, a fonte.',
      c:'Não «melhore» a citação sem o assinalar. Uma epígrafe no início de um livro ou capítulo leva o nome do autor e, normalmente, o título da obra, sem aspas, em linha própria.',
      x:['Sinal da citação: Ela perguntou: «Quem és tu?»', 'Sinal da frase: Quem disse que «a vida é sonho»?', 'Corte: «O mar [...] não devolve nada», escreveu ela.'],
      t:'As Referências do projeto guardam as fontes das citações (Documents e Links). Associe-as à Cena ou à Personagem que as usa, para as encontrar na revisão.',
      s:['Aspas', 'Parênteses retos', 'Reticências', 'Intertextualidade'] }
  ]},

  { name:'Pontuação, estilo e revisão', items:[
    { n:'Pontuação e ritmo', a:'A pontuação como partitura da prosa',
      d:'A pontuação não serve só a gramática: é a principal ferramenta de ritmo de um texto. Frases curtas e pontos frequentes aceleram e dão tensão; frases longas, com vírgulas e ponto e vírgula, abrandam e envolvem; os travessões e os parênteses mudam o tom de voz.',
      u:'Numa cena de ação, corte: pontos, frases curtas, poucas subordinadas. Numa cena de memória ou de contemplação, deixe a frase respirar. Numa revisão, leia em voz alta e marque onde tropeça: quase sempre é uma vírgula a mais, a menos, ou uma frase que pedia um ponto. Varie: o mesmo comprimento de frase durante páginas adormece o leitor.',
      c:'O ritmo não justifica o erro: uma vírgula entre o sujeito e o verbo continua errada, por mais natural que soe a pausa. A pontuação expressiva só funciona sobre um fundo de pontuação correta.',
      x:['Tensão: «Ouviu passos. Parou. Os passos também.»', 'Contemplação: «Ficou à janela até tarde, a ver as luzes dos barcos a apagarem-se uma a uma, como se alguém, muito longe, fosse fechando a casa.»'],
      t:'Na Ordem Narrativa do quadro, uma sequência de Cenas de ação seguidas pede, muitas vezes, uma Cena mais lenta a seguir. O mesmo princípio vale dentro da frase.',
      s:['Ritmo da frase', 'Frase curta', 'Frase longa', 'Pontuação expressiva', 'Ritmo narrativo'] },
    { n:'Pontuação de autor', a:'Saramago, Lobo Antunes, Gonçalo M. Tavares, Joyce, McCarthy, Gertrude Stein',
      d:'Muitos escritores fazem da pontuação uma marca de estilo: suprimem-na, reduzem-na ou reinventam-na. Conhecer estes usos ajuda a perceber que a pontuação é uma escolha — e que só se pode quebrar com proveito uma regra que se domina.',
      u:'Saramago: vírgula e ponto quase como únicos sinais, falas marcadas pela maiúscula. António Lobo Antunes: frases entrecortadas, vozes sobrepostas, parágrafos que mudam de voz a meio. Gonçalo M. Tavares: frases curtas e secas, textos por vezes em fragmentos numerados. James Joyce, em «Penélope», o monólogo de Molly Bloom que fecha *Ulisses*: dezenas de páginas em oito longuíssimas «frases», quase sem pontuação, a imitar o pensamento. Cormac McCarthy: diálogos sem aspas e poucas vírgulas. Gertrude Stein: repetição e quase nenhuma vírgula, que ela considerava desnecessária. Use estes modelos como laboratório: reescreva uma cena sua à maneira de um deles e veja o que muda.',
      c:'Imitar a superfície (tirar as vírgulas) sem o propósito por trás dá um texto difícil sem recompensa. Num primeiro livro, a pontuação invulgar é muitas vezes lida pelos editores como descuido.',
      x:['Exercício: escrever a mesma cena três vezes — com pontuação normal, com frases curtíssimas e sem nenhuma pontuação — e comparar o efeito.'],
      s:['Pontuação expressiva', 'Diálogo sem marcas', 'Fluxo de consciência', 'Escrita sob restrição', 'Pastiche e paródia'] },
    { n:'Erros frequentes de pontuação', a:'Lista de verificação para a revisão',
      d:'Os erros de pontuação que mais aparecem em manuscritos, por ordem aproximada de frequência. Servem como lista de verificação numa revisão por camadas.',
      u:'Procure, um de cada vez: 1) vírgula entre sujeito e verbo; 2) vírgula de fecho esquecida num inciso; 3) orações com uma relação forte (causa, contraste) ligadas só por vírgula, onde um ponto, um ponto e vírgula ou uma conjunção ajudariam o leitor; 4) hífen em vez de travessão; 5) ponto final antes do travessão do verbo declarativo; 6) vírgula depois de «mas» ou antes de «que» completivo; 7) reticências a mais; 8) pontos de exclamação a mais; 9) aspas para dar ênfase; 10) espaço antes de «?», «!», «:» e «;»; 11) mistura de aspas angulares e retas, ou de travessões e aspas nas falas; 12) dois pontos sem nada a anunciar.',
      c:'Os corretores automáticos apanham poucos destes erros, e alguns «corrigem» o certo (trocam travessões por hífenes, aspas angulares por retas). Faça uma passagem só para pontuação, em voz alta, de preferência em papel ou noutro formato.',
      x:['«O homem que vendia peixe, desapareceu.» → «O homem que vendia peixe desapareceu.»', 'Relação pouco clara: «Estava a chover, ficaram em casa.» → mais claro: «Estava a chover; ficaram em casa.» ou «Como estava a chover, ficaram em casa.»', '— Vou sair. — disse ele. → — Vou sair — disse ele.'],
      t:'Crie uma Nota «Revisão: pontuação» associada a cada Tomo e vá marcando os Capítulos já revistos. Na ficha do Tomo, as Notas associadas ficam sempre à mão.',
      s:['Vírgula: quando não usar', 'Revisão por camadas', 'Hífen, meia-risca e travessão', 'Pontuação do diálogo com travessão'] }
  ]}
  ]});
